def collatz_sequence(num):
    """Generate the Collatz sequence for a given number."""
    sequence = []
    while num != 1:
        sequence.append(num)
        if num % 2 == 0:
            num //= 2
        else:
            num = 3 * num + 1
    sequence.append(1)
    return sequence

