def rearange_string(s):
  count = Counter(s)
  max_count = max(count.values())
  if max_count > len(s)//2:
    return "impossible"
  else:
    sorted_chars = sorted(count.keys(), key=lambda x: count[x])
    result = []
    for char in sorted_chars:
      while count[char] > 0:
        result.append(char)
        result.append(char)
        count[char] -= 2
    return ''.join(result)

