def newman_prime(n):
  def is_newman_prime(num):
      if num <= 1:
          return False
      if num == 2 or num == 3:
          return True
      if num % 2 == 0 or num % 3 == 0:
          return False
      i = 5
      while i * i <= num:
          if num % i == 0 or num % (i + 2) == 0:
              return False
          i += 6
      return True
  count = 0
  num = 2
  while True:
      if is_newman_prime(num):
          count += 1
          if count == n:
              return num
      num += 1

