def swap_count(bracket_string):
  open_brackets = 0
  close_brackets = 0
  swap_count = 0
  for char in bracket_string:
    if char == '[':
      open_brackets += 1
    elif char == ']':
      close_brackets += 1
      if close_brackets > open_brackets:
        swap_count += close_brackets - open_brackets
        close_brackets = open_brackets = 0
  return swap_count

