  for num in nums:
    if isinstance(num, int):
      total_sum += sum(int(digit) for digit in str(abs(num)))
    elif isinstance(num, list):
      total_sum += sum(sum(int(digit) for digit in str(abs(sub_num))) for sub_num in num)
  return total_sum

