def k_smallest_pairs(arr1,arr2,k): 
  arr1.sort()
  arr2.sort()
  res = []
  while len(res) < k:
    if arr1[0] <= arr2[-1]:
      res.append([arr1[0],arr2.pop()])
      arr1.pop(0)
    else:
      res.append([arr2.pop(),arr1[0]])
      arr2.pop(-1)
  return res

