def parabola_directrix(a,b,c):
  discriminant = b**2 - 4*a*c
  if discriminant < 0:
    return None
  else:
    x = (-b + math.sqrt(discriminant)) / (2*a)
    y = a*x**2 + b*x + c
    return -y

